-- Complete record links and audit evidence export, with the same tenant/store boundary.
create or replace function private.audit_record_v704(t uuid,dataset text,rid text,loc uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb;r jsonb;tenant_clause text;sensitive boolean;
begin
 perform private.audit_access_v703(t,loc);
 select value into cfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=dataset;
 if cfg is null or length(coalesce(rid,''))>80 then raise exception 'Invalid record selector' using errcode='22023';end if;
 sensitive:=private.has_permission(t,'audit_history.view_sensitive');
 tenant_clause:=case when (cfg->>'tenant_column')::boolean then 'x.tenant_id=$1' else format('exists(select 1 from public.%I p where p.tenant_id=$1 and p.id=x.%I)',cfg#>>'{parent,1}',cfg#>>'{parent,0}') end;
 execute format('select private.audit_clean_v704(to_jsonb(x),$4) from public.%I x where %s and coalesce(to_jsonb(x)->>''id'',md5(private.audit_clean_v704(to_jsonb(x),$4)::text))=$2 and private.audit_record_allowed_v704($1,$5,to_jsonb(x),$3)',dataset,tenant_clause)
 into r using t,rid,loc,sensitive,dataset;
 if r is null then raise exception 'Evidence record unavailable' using errcode='42501';end if;return r;
end $$;
revoke all on function private.audit_record_v704(uuid,text,text,uuid) from public,anon,authenticated;

create or replace function private.audit_detail_v704(t uuid,dataset text,rid text,loc uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare r jsonb;cfg jsonb;links jsonb:='[]';x record;p jsonb;pcfg jsonb;childcfg jsonb;child_count bigint;tenant_clause text;journals jsonb;events jsonb;warnings jsonb:='[]';
begin
 r:=private.audit_record_v704(t,dataset,rid,loc);
 select value into cfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=dataset;
 -- FK-derived links, restricted to the reviewed allowlist and authorised stores.
 for x in
  select pn.relname parent,cn.relname child,pa.attname parent_key,ca.attname child_key
  from pg_catalog.pg_constraint fk join pg_catalog.pg_class cn on cn.oid=fk.conrelid join pg_catalog.pg_class pn on pn.oid=fk.confrelid
  join lateral unnest(fk.conkey,fk.confkey) keys(ca,pa) on true
  join pg_catalog.pg_attribute ca on ca.attrelid=cn.oid and ca.attnum=keys.ca
  join pg_catalog.pg_attribute pa on pa.attrelid=pn.oid and pa.attnum=keys.pa
  where fk.contype='f' and fk.connamespace='public'::regnamespace and (cn.relname=dataset or pn.relname=dataset) and ca.attname<>'tenant_id' and pa.attname='id'
 loop
  if x.child=dataset and nullif(r->>x.child_key,'') is not null then
   select value into pcfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=x.parent;
   if pcfg is not null then
    begin p:=private.audit_record_v704(t,x.parent,r->>x.child_key,loc);
     links:=links||jsonb_build_array(jsonb_build_object('dataset',x.parent,'label',pcfg->>'label','record_id',r->>x.child_key,'relation','Linked '||replace(x.child_key,'_',' '),'count',1));
    exception when insufficient_privilege then null;end;
   end if;
  elsif x.parent=dataset and r->>'id' is not null then
   select value into childcfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=x.child;
   if childcfg is not null then
    tenant_clause:=case when (childcfg->>'tenant_column')::boolean then 'c.tenant_id=$1' else 'true' end;
    execute format('select count(*) from public.%I c where %s and c.%I::text=$2 and private.audit_record_allowed_v704($1,$3,to_jsonb(c),$4)',x.child,tenant_clause,x.child_key)
    into child_count using t,r->>'id',x.child,loc;
    if child_count>0 then links:=links||jsonb_build_array(jsonb_build_object('dataset',x.child,'label',childcfg->>'label','relation','Related records','match_key',x.child_key,'match_value',r->>'id','count',child_count));end if;
   end if;
  end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'entry_number',j.entry_number,'date',j.entry_date,'status',j.status,'source_type',j.source_type,'reversal_of',j.reversal_of) order by j.entry_date,j.id),'[]') into journals
 from public.journal_entries j where j.tenant_id=t and private.reports_scope_v631(t,j.location_id,loc,'view') and
  (j.id::text=r->>'journal_id' or (dataset='journal_entries' and (j.id::text=rid or j.reversal_of::text=rid)) or (j.source_id::text=r->>'id' and cfg->'sources' ? j.source_type));
 select coalesce(jsonb_agg(jsonb_build_object('dataset','transaction_story_events_v600','label',e.action,'record_id',e.id,'date',e.event_time,'actor',e.actor_name,'quality',case when coalesce((e.metadata->>'historical_reconstruction')::boolean,false) then 'Historical baseline' else 'Recorded event' end) order by e.event_time),'[]') into events
 from public.transaction_story_events_v600 e where e.tenant_id=t and e.entity_id::text=r->>'id' and e.entity_type=cfg->>'entity' and private.audit_record_allowed_v704(t,'transaction_story_events_v600',to_jsonb(e),loc);
 if jsonb_array_length(events)=0 then warnings:=warnings||jsonb_build_array('No native change history linked to this record. Saved values do not prove earlier edits were captured.');end if;
 return jsonb_build_object('dataset',cfg->>'label','record',r,'links',links,'journals',journals,'events',events,'warnings',warnings,'sensitive_values_visible',private.has_permission(t,'audit_history.view_sensitive'));
end $$;
